'barangay-clearance'=>['Request Documents','DOCUMENT','DOCUMENT_REQUEST'],
'incident-report'=>['File a Report','REPORT','INCIDENT_REPORT'],
'medicine-assistance'=>['Request Medicine','MEDICINE','MEDICINE_REQUEST']
];
$key=(string)($_GET['type']??'barangay-clearance');
